package com.nimbusbill.customer.repository;
import com.nimbusbill.customer.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface PricingPlanVersionRepository extends JpaRepository<PricingPlanVersion,UUID>{List<PricingPlanVersion> findByPlanIdOrderByVersionNumberDesc(UUID planId);Optional<PricingPlanVersion> findFirstByPlanIdAndStatusOrderByVersionNumberDesc(UUID planId,PricingVersionStatus status);@Query("select v from PricingPlanVersion v where v.plan.id=:planId and v.status='ACTIVE' and v.effectiveFrom<=:date and (v.effectiveTo is null or v.effectiveTo>=:date) order by v.versionNumber desc") List<PricingPlanVersion> active(@Param("planId") UUID planId,@Param("date") LocalDate date);}
